import '@fontsource/dm-sans/500.css';
import '@fontsource/dm-sans/600.css';
import '@fontsource/dm-sans/700.css';
import '@fontsource/dm-serif-display/400.css';
import { GraduationCap, ArrowRight, ArrowLeft, ArrowUpRight, House, UsersThree, Books, DotsThree, X, Plus, MagnifyingGlass, SlidersHorizontal, DownloadSimple, CheckCircle, Clock, Phone, WhatsappLogo, NotePencil, CalendarBlank, MapPin, Monitor, Check, WarningCircle, ArrowCounterClockwise, CaretRight, Archive, GlobeHemisphereWest } from '@phosphor-icons/react';
import { demoConfig, formatCurrency } from './config.js';
import { STORE_KEY, STATUSES, uid, isoNow, dayKey, localDateTime, fromLocalDateTime, displayDate, normalizePhone, inquiryErrors, openReminder, reminderBucket, seedStore, readStore, validStore, submitInquiry, updateRequest, saveProgram, filterRequests, toCsv } from './store.js';
